//! Phase 2 gate: RHF/UHF total energies against the frozen PySCF oracle
//! (`tests/oracle_data/*_scf.csv`, generated by `tools/oracle/gen_scf.py`),
//! plus internal-consistency gates (DIIS on/off, in-core vs direct).

use dft_rs::basis::{data, MolBasis};
use dft_rs::math::Vec3;
use dft_rs::scf::{run_hf, EriMode, ScfOptions};
use dft_rs::system::{Atom, Molecule};

struct OracleCase {
    name: String,
    basis: String,
    molecule: Molecule,
    method: String,
    e_tot: f64,
    e_nuc: f64,
    s2: Option<f64>,
}

fn load_cases() -> Vec<OracleCase> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/oracle_data");
    let mut cases = Vec::new();
    for entry in std::fs::read_dir(&dir).unwrap().flatten() {
        let path = entry.path();
        let fname = path.file_name().unwrap().to_string_lossy().to_string();
        if !fname.ends_with("_scf.csv") {
            continue;
        }
        let text = std::fs::read_to_string(&path).unwrap();
        let mut basis = String::new();
        let mut charge = 0i32;
        let mut mult = 1usize;
        let mut method = String::new();
        let mut atoms = Vec::new();
        let (mut e_tot, mut e_nuc, mut s2) = (f64::NAN, f64::NAN, None);
        for line in text.lines().filter(|l| !l.starts_with('#')) {
            let parts: Vec<&str> = line.split(',').collect();
            match parts[0] {
                "basis" => basis = parts[1].to_string(),
                "charge" => charge = parts[1].parse().unwrap(),
                "mult" => mult = parts[1].parse().unwrap(),
                "method" => method = parts[1].to_string(),
                "atom" => atoms.push(Atom {
                    z: parts[1].parse().unwrap(),
                    position: Vec3::new(
                        parts[2].parse().unwrap(),
                        parts[3].parse().unwrap(),
                        parts[4].parse().unwrap(),
                    ),
                }),
                "e_tot" => e_tot = parts[1].parse().unwrap(),
                "e_nuc" => e_nuc = parts[1].parse().unwrap(),
                "s2" => s2 = Some(parts[1].parse().unwrap()),
                other => panic!("unknown oracle key {other}"),
            }
        }
        cases.push(OracleCase {
            name: fname.trim_end_matches("_scf.csv").to_string(),
            basis,
            molecule: Molecule::new(atoms)
                .with_charge(charge)
                .with_multiplicity(mult),
            method,
            e_tot,
            e_nuc,
            s2,
        });
    }
    assert!(
        cases.len() >= 20,
        "expected the full oracle set, found {}",
        cases.len()
    );
    cases
}

fn tight_options() -> ScfOptions {
    ScfOptions {
        e_tol: 1e-11,
        p_tol: 1e-9,
        max_iter: 200,
        eri_mode: EriMode::InCore { limit_mb: 512 },
        ..ScfOptions::default()
    }
}

#[test]
fn hf_energies_match_pyscf_oracle() {
    let mut failures = Vec::new();
    for case in load_cases() {
        let set = data::load(&case.basis).unwrap();
        let mb = MolBasis::build(&case.molecule, &set).unwrap();
        let mut opts = tight_options();
        if case.method == "uhf" {
            // Degenerate open-shell cases converge more reliably shifted.
            opts.level_shift = 0.2;
        }
        let scf = match run_hf(&case.molecule, &mb, &opts) {
            Ok(s) => s,
            Err(e) => {
                failures.push(format!("{}: SCF failed: {e}", case.name));
                continue;
            }
        };
        let tol = if case.method == "uhf" { 1e-7 } else { 1e-8 };
        if (scf.e_nuc - case.e_nuc).abs() > 1e-10 {
            failures.push(format!(
                "{}: E_nuc {} vs oracle {}",
                case.name, scf.e_nuc, case.e_nuc
            ));
        }
        if (scf.energy - case.e_tot).abs() > tol {
            failures.push(format!(
                "{}: E {} vs oracle {} (Δ = {:.3e})",
                case.name,
                scf.energy,
                case.e_tot,
                scf.energy - case.e_tot
            ));
        }
        if let Some(s2) = case.s2 {
            if (scf.s_squared - s2).abs() > 1e-5 {
                failures.push(format!(
                    "{}: <S²> {} vs oracle {}",
                    case.name, scf.s_squared, s2
                ));
            }
        }
        assert_eq!(scf.unrestricted, case.method == "uhf", "{}", case.name);
    }
    assert!(
        failures.is_empty(),
        "oracle failures:\n{}",
        failures.join("\n")
    );
}

/// The converged energy must not depend on the acceleration path.
#[test]
fn diis_on_off_and_incore_direct_agree() {
    let mol = Molecule::new(vec![
        Atom {
            z: 8,
            position: Vec3::new(0.0, 0.0, 0.2217),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, 1.4309, -0.8867),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, -1.4309, -0.8867),
        },
    ]);
    let set = data::load("sto-3g").unwrap();
    let mb = MolBasis::build(&mol, &set).unwrap();

    let base = tight_options();
    let e_ref = run_hf(&mol, &mb, &base).unwrap().energy;

    let mut no_diis = tight_options();
    no_diis.use_diis = false;
    no_diis.max_iter = 500;
    let e_nodiis = run_hf(&mol, &mb, &no_diis).unwrap().energy;
    assert!(
        (e_ref - e_nodiis).abs() < 1e-9,
        "DIIS on/off disagree: {e_ref} vs {e_nodiis}"
    );

    let mut direct = tight_options();
    direct.eri_mode = EriMode::Direct {
        screen_threshold: 1e-13,
    };
    let e_direct = run_hf(&mol, &mb, &direct).unwrap().energy;
    assert!(
        (e_ref - e_direct).abs() < 1e-10,
        "in-core vs direct disagree: {e_ref} vs {e_direct}"
    );
}

/// Guess independence: core and GWH guesses must reach the same minimum on
/// a well-behaved closed shell. (N2 is deliberately NOT used here: the bare
/// core guess famously converges it to an excited SCF solution — that is a
/// guess-quality property, not an implementation bug.)
#[test]
fn guess_independence() {
    let mol = Molecule::new(vec![
        Atom {
            z: 8,
            position: Vec3::new(0.0, 0.0, 0.2217),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, 1.4309, -0.8867),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, -1.4309, -0.8867),
        },
    ]);
    let set = data::load("sto-3g").unwrap();
    let mb = MolBasis::build(&mol, &set).unwrap();
    let gwh = run_hf(&mol, &mb, &tight_options()).unwrap().energy;
    let mut core_opts = tight_options();
    core_opts.guess = dft_rs::scf::Guess::Core;
    core_opts.max_iter = 300;
    let core = run_hf(&mol, &mb, &core_opts).unwrap().energy;
    assert!(
        (gwh - core).abs() < 1e-9,
        "guess dependence: {gwh} vs {core}"
    );
}
